#!/usr/bin/env python3
"""RoboPaint limited-mode trajectory for copying 花 with a Panda writing brush.

Run `python /app/output/gen.py --phase top`, inspect main_top_canvas_cam.png,
then `python /app/output/gen.py --phase bottom`. `--phase all` runs all seven.
The optional `--phase calibrate` makes pressure trials on the unscored practice sheet.
"""
import sys, json, math, argparse, pathlib
import numpy as np
sys.path.insert(0, '/opt/tools')
from rcb_client import Robot

OUT = pathlib.Path('/app/output')
DT = 0.05
MAX_STEP = 0.0050  # 0.10 m/s targets, below the client speed cap
Q = np.array([0.0, 1.0, 0.0, 0.0], dtype=float)  # brush straight down (wxyz)
MM_PER_PX = 0.227185 / 1024.0
r = Robot()


def status(label):
    s = r.status()
    print(label, json.dumps({k:s.get(k) for k in ('step','calls','control_steps','elapsed_s','done','reason')}), flush=True)
    return s


def get_obs():
    return r.get_obs(cameras=('canvas_cam','practice_cam','scene_cam','side_cam'), video='none')


def get_tip():
    o = r.get_obs(video='none')
    return np.asarray(o.meta['proprio']['now'][7:10], float)


def to_xyz(u, v, z):
    """Exact target-pixel centre to main-sheet world conversion from spec."""
    X = (float(u) + 0.5) * MM_PER_PX
    Y = (float(v) + 0.5) * MM_PER_PX
    x = -0.100 + 0.227185/2 - Y
    y = 0.227185/2 - X
    return np.array([x, y, float(z)], dtype=float)


def rows_for(points, start=None):
    """XYZ waypoints to dense 20 Hz Cartesian targets, with bounded xyz increments."""
    if start is None: start = get_tip()
    rows=[]; cur=np.asarray(start, float)
    for p in points:
        p=np.asarray(p,float)
        n=max(1, int(math.ceil(float(np.linalg.norm(p-cur))/MAX_STEP)))
        for f in np.linspace(1/n,1,n): rows.append(np.r_[cur+(p-cur)*f,Q])
        cur=p
    return np.asarray(rows,np.float32)


def send_rows(rows, note):
    rows=np.asarray(rows,np.float32)
    for i in range(0,len(rows),180):
        chunk=rows[i:i+180]
        res=r.submit('ee_pose', chunk, dt=DT, video='none',
                     cameras=('canvas_cam','practice_cam','scene_cam','side_cam'), note=note)
        plan=res.meta.get('plan',[])
        failures=sum(int(x.get('ik_failures',0)) for x in plan if isinstance(x,dict))
        slowed=sum(bool(x.get('slowed',False)) for x in plan if isinstance(x,dict))
        print('action',note,'rows',len(chunk),'steps',res.meta.get('control_steps_chunk'),
              'IK_failures',failures,'slowed_rows',slowed,'time_left',res.meta.get('time_left_s'),flush=True)
        if res.done: raise RuntimeError('episode ended during '+note)
    return get_tip()


def move_xyz(points, note):
    p=get_tip()
    return send_rows(rows_for(points,start=p),note)


def save_views(tag):
    from PIL import Image
    o=get_obs()
    for cam,img in o.last.items(): Image.fromarray(img).save(OUT/f'{tag}_{cam}.png')
    print(tag,'tip',o.meta['proprio']['now'][7:10], 'time_left',o.meta.get('time_left_s'),flush=True)
    return o


def dip(note='refresh_ink'):
    # Ink surface z=0.028 m; a settled tip at z=0.020 is 8 mm into the ink.
    move_xyz([[-0.100,0.150,0.060],[-0.100,0.150,0.020]]+[[-0.100,0.150,0.020]]*14+
             [[-0.100,0.150,0.060]]*5,note)


# Pixel centreline samples in the exemplar. Each tuple is (u, v, tip z in m).
# Depth changes set the brush width: shallow on the hairline, deeper in broad strokes.
STROKES = {
  1: [(282,344,.0160),(320,345,.0160),(380,344,.0160),(445,340,.0160),(510,336,.0160),(580,332,.0160),(650,328,.0160),(712,324,.0160),(738,321,.0160)],
  2: [(407,252,.0145),(410,265,.0145),(414,284,.0145),(419,307,.0145),(423,330,.0145),(428,354,.0145),(433,378,.0145),(439,397,.0145)],
  3: [(581,216,.0135),(590,230,.0135),(590,247,.0135),(584,273,.0135),(577,300,.0135),(568,329,.0135),(558,357,.0135),(548,383,.0135),(539,405,.0135)],
  4: [(410,432,.0135),(408,450,.0140),(402,473,.0145),(390,496,.0145),(374,520,.0145),(354,545,.0145),(331,570,.0145),(306,594,.0145),(280,617,.0150),(255,640,.0160),(237,657,.0170)],
  5: [(374,555,.0160),(391,565,.0150),(405,579,.0145),(400,596,.0145),(397,623,.0145),(394,652,.0145),(391,682,.0145),(389,712,.0140),(388,742,.0135),(390,763,.0125),(389,774,.0125)],
  6: [(681,474,.0115),(670,483,.0130),(652,498,.0160),(628,518,.0165),(601,539,.0165),(572,561,.0165),(541,584,.0165),(510,607,.0165),(480,630,.0165),(454,650,.0170),(443,663,.0180)],
  7: [(526,438,.0120),(528,459,.0115),(529,483,.0115),(528,510,.0115),(527,540,.0115),(526,570,.0115),(527,600,.0115),(528,628,.0115),(532,655,.0110),(539,680,.0105),(552,702,.0100),(572,720,.0100),(600,736,.0100),(633,747,.0100),(668,750,.0100),(701,747,.0100),(731,738,.0105),(756,724,.0110),(777,706,.0115),(783,692,.0120),(776,670,.0135),(768,644,.0150),(761,621,.0170)]
}


def draw_stroke(n):
    pixels=STROKES[n]
    path=[to_xyz(u,v,z) for u,v,z in pixels]
    # Start and end above the sheet. Press, move continuously, and lift before repositioning.
    above_start=path[0].copy(); above_start[2]=0.060
    above_end=path[-1].copy(); above_end[2]=0.060
    move_xyz([above_start],f's{n}_position')
    move_xyz([path[0],path[0],path[0]],f's{n}_press')
    move_xyz(path[1:],f's{n}_draw')
    move_xyz([above_end]+[above_end]*5,f's{n}_lift')
    print('completed_stroke',n,'start_px',pixels[0][:2],'end_px',pixels[-1][:2],flush=True)


def clear_and_review(tag):
    move_xyz([[0.0,-0.180,0.160]],f'{tag}_camera_clear')
    save_views(tag)


def main_top():
    dip()
    for n in (1,2,3): draw_stroke(n)
    clear_and_review('main_top')


def main_bottom():
    for n in (4,5,6,7): draw_stroke(n)
    clear_and_review('main_final')


def calibrate():
    """Optional pressure checks on the practice sheet only."""
    dip('calibration_dip')
    # Pressure depths 2, 4, 8, 10, and 12 mm; each line is isolated and unscored.
    for idx,(x,z) in enumerate([(-.075,.018),(-.125,.016),(-.100,.012),(-.025,.010),(-.050,.008)]):
        y0,y1=(-.222,-.150) if idx%2==0 else (-.150,-.222)
        p0=[x,y0,.055]; a=[x,y0,z]; b=[x,y1,z]; p1=[x,y1,.055]
        move_xyz([p0,a,a,b,p1],f'practice_pressure_{idx+1}')
    clear_and_review('calibration')


if __name__ == '__main__':
    ap=argparse.ArgumentParser()
    ap.add_argument('--phase',choices=('calibrate','top','bottom','all'),default='all')
    args=ap.parse_args()
    status('connected')
    if args.phase=='calibrate': calibrate()
    elif args.phase=='top': main_top()
    elif args.phase=='bottom': main_bottom()
    else:
        dip()
        for n in range(1,8):
            draw_stroke(n)
            if n==3: clear_and_review('main_top')
        clear_and_review('main_final')
    status('finished')
